package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.Contribuicao; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/contribuicoes") public class ContribuicaoRestController { final ContribuicaoApplicationService s; public ContribuicaoRestController(ContribuicaoApplicationService s){this.s=s;} @PostMapping public Contribuicao criar(@Valid @RequestBody ContribuicaoRequest r){return s.salvar(r);} @GetMapping public List<Contribuicao> listar(){return s.listar();} }